import { Field, FieldContent, FieldDescription, FieldLabel } from "@/registry/erbium/ui/field";
import { Switch } from "@/registry/erbium/ui/switch";

export function SwitchInvalid() {
  return (
    <Field orientation="horizontal" className="max-w-sm" invalid>
      <FieldContent>
        <FieldLabel>Accept terms and conditions</FieldLabel>
        <FieldDescription>You must accept the terms and conditions to continue.</FieldDescription>
      </FieldContent>
      <Switch />
    </Field>
  );
}

import { SwitchInvalid } from "../examples/upstream/switch-invalid";

const Example = () => <SwitchInvalid />;

export default Example;
